// GENERATED by scripts/crop_blades.sh — do not edit by hand.
// Re-run the script after changing, adding or reordering the artwork, then copy
// the new file over this one.
//
// Each blade was drawn on a full canvas, then cropped to its own bounds.
// left/top/width are where it sat on that canvas, as a percentage, so placing it
// with those numbers puts it back exactly where it was drawn.
//
// Height is deliberately NOT recorded: setting only the width lets the image
// keep its own aspect ratio, so a blade can never come out squashed.

export interface PlacedBlade {
  /** File name within the blade art folder. */
  img: string;
  /** Position on the original canvas, as % of its width / height. */
  left: number;
  top: number;
  /** Width as % of the canvas width. */
  width: number;
}

/**
 * Empty until the artwork is run through scripts/crop_blades.sh — the scene
 * falls back to the old computed field (BladeField) in the meantime, so the
 * page works either way.
 */
export const BLADES: PlacedBlade[] = [];
